import{_ as i,o as a,c as e,a0 as n}from"./chunks/framework.DCluYYrN.js";const c=JSON.parse('{"title":"Module Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/module-config.md","filePath":"guide/module-config.md"}'),t={name:"guide/module-config.md"};function l(o,s,r,h,p,d){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="module-configuration" tabindex="-1">Module Configuration <a class="header-anchor" href="#module-configuration" aria-label="Permalink to &quot;Module Configuration&quot;">​</a></h1><p>KernelSU provides a built-in configuration system that allows modules to store persistent or temporary key-value settings. Configurations are stored in a binary format at <code>/data/adb/ksu/module_configs/&lt;module_id&gt;/</code> with the following characteristics:</p><h2 id="configuration-types" tabindex="-1">Configuration Types <a class="header-anchor" href="#configuration-types" aria-label="Permalink to &quot;Configuration Types&quot;">​</a></h2><ul><li><strong>Persist Config</strong> (<code>persist.config</code>): Survives reboots and persists until explicitly deleted or the module is uninstalled</li><li><strong>Temp Config</strong> (<code>tmp.config</code>): Automatically cleared during the post-fs-data stage on every boot</li></ul><p>When reading configurations, temporary values take priority over persistent values for the same key.</p><h2 id="using-configuration-in-module-scripts" tabindex="-1">Using Configuration in Module Scripts <a class="header-anchor" href="#using-configuration-in-module-scripts" aria-label="Permalink to &quot;Using Configuration in Module Scripts&quot;">​</a></h2><p>All module scripts (<code>post-fs-data.sh</code>, <code>service.sh</code>, <code>boot-completed.sh</code>, etc.) run with the <code>KSU_MODULE</code> environment variable set to the module ID. You can use the <code>ksud module config</code> commands to manage your module&#39;s configuration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Get a configuration value</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">value</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_setting</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set a persistent configuration value</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_setting</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;some value&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set a temporary configuration value (cleared on reboot)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --temp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> runtime_state</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;active&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set value from stdin (useful for multiline or complex data)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">multiline</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">text value</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or pipe from command</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;value&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_key</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Explicit stdin flag</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json_data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stdin</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># List all configuration entries (merged persist + temp)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Delete a configuration entry</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_setting</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Delete a temporary configuration entry</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --temp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> runtime_state</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clear all persistent configurations</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clear all temporary configurations</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --temp</span></span></code></pre></div><h2 id="validation-limits" tabindex="-1">Validation Limits <a class="header-anchor" href="#validation-limits" aria-label="Permalink to &quot;Validation Limits&quot;">​</a></h2><p>The configuration system enforces the following limits:</p><ul><li><strong>Maximum key length</strong>: 256 bytes</li><li><strong>Maximum value length</strong>: 1MB (1048576 bytes)</li><li><strong>Maximum config entries</strong>: 32 per module</li><li><strong>Key format</strong>: Must match <code>^[a-zA-Z][a-zA-Z0-9._-]+$</code> (same as module ID) <ul><li>Must start with a letter (a-zA-Z)</li><li>Can contain letters, numbers, dots (<code>.</code>), underscores (<code>_</code>), or hyphens (<code>-</code>)</li><li>Minimum length: 2 characters</li></ul></li><li><strong>Value format</strong>: No restrictions - can contain any UTF-8 characters including newlines, control characters, etc. <ul><li>Stored in binary format with length prefix, ensuring safe handling of all data</li></ul></li></ul><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><ul><li><strong>On boot</strong>: All temporary configurations are cleared during the post-fs-data stage</li><li><strong>On module uninstall</strong>: All configurations (both persist and temp) are removed automatically</li><li>Configurations are stored in a binary format with magic number <code>0x4b53554d</code> (&quot;KSUM&quot;) and version validation</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><p>The configuration system is ideal for:</p><ul><li><strong>User preferences</strong>: Store module settings that users configure through WebUI or action scripts</li><li><strong>Feature flags</strong>: Enable/disable module features without reinstalling</li><li><strong>Runtime state</strong>: Track temporary state that should reset on reboot (use temp config)</li><li><strong>Installation settings</strong>: Remember choices made during module installation</li><li><strong>Complex data</strong>: Store JSON, multiline text, Base64 encoded data, or any structured content (up to 1MB)</li></ul><div class="tip custom-block"><p class="custom-block-title">BEST PRACTICES</p><ul><li>Use persistent configs for user preferences that should survive reboots</li><li>Use temporary configs for runtime state or feature toggles that should reset on boot</li><li>Validate configuration values in your scripts before using them</li><li>Use the <code>ksud module config list</code> command to debug configuration issues</li></ul></div><h2 id="advanced-features" tabindex="-1">Advanced Features <a class="header-anchor" href="#advanced-features" aria-label="Permalink to &quot;Advanced Features&quot;">​</a></h2><p>The module configuration system provides special configuration keys for advanced use cases:</p><h3 id="overriding-module-description" tabindex="-1">Overriding Module Description <a class="header-anchor" href="#overriding-module-description" aria-label="Permalink to &quot;Overriding Module Description {#overriding-module-description}&quot;">​</a></h3><p>You can dynamically override the <code>description</code> field from <code>module.prop</code> by setting the <code>override.description</code> configuration key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Override module description</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> override.description</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Custom description shown in the manager&quot;</span></span></code></pre></div><p>When the module list is retrieved, if the <code>override.description</code> config exists, it will replace the original description from <code>module.prop</code>. This is useful for:</p><ul><li>Displaying dynamic status information in the module description</li><li>Showing runtime configuration details to users</li><li>Updating description based on module state without reinstalling</li></ul><h3 id="declaring-managed-features" tabindex="-1">Declaring Managed Features <a class="header-anchor" href="#declaring-managed-features" aria-label="Permalink to &quot;Declaring Managed Features&quot;">​</a></h3><p>Modules can declare which KernelSU features they manage using the <code>manage.&lt;feature&gt;</code> configuration pattern. The supported features correspond to KernelSU&#39;s internal <code>FeatureId</code> enum:</p><p><strong>Supported Features:</strong></p><ul><li><code>su_compat</code> - SU compatibility mode</li><li><code>kernel_umount</code> - Kernel automatic unmount</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Declare that this module manages SU compatibility and enables it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.su_compat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Declare that this module manages kernel unmount and disables it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.kernel_umount</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Remove feature management (module no longer controls this feature)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage.su_compat</span></span></code></pre></div><p><strong>How it works:</strong></p><ul><li>The presence of a <code>manage.&lt;feature&gt;</code> key indicates the module is managing that feature</li><li>The value indicates the desired state: <code>true</code>/<code>1</code> for enabled, <code>false</code>/<code>0</code> (or any other value) for disabled</li><li>To stop managing a feature, delete the configuration key entirely</li></ul><p>Managed features are exposed through the module list API as a <code>managedFeatures</code> field (comma-separated string). This allows:</p><ul><li>KernelSU manager to detect which modules manage which KernelSU features</li><li>Prevention of conflicts when multiple modules try to manage the same feature</li><li>Better coordination between modules and core KernelSU functionality</li></ul><div class="warning custom-block"><p class="custom-block-title">SUPPORTED FEATURES ONLY</p><p>Only use the predefined feature names listed above (<code>su_compat</code>, <code>kernel_umount</code>). These correspond to actual KernelSU internal features. Using other feature names will not cause errors but serves no functional purpose.</p></div>`,34)])])}const u=i(t,[["render",l]]);export{c as __pageData,u as default};
